import Component from 'flarum/common/Component';
/** The row of tabs across the top of the Millwright page. */
export default class PageTabs extends Component {
  view() {
    return m("div", {
      className: "Millwright-tabs",
      role: "tablist"
    }, this.attrs.tabs.map(tab => m("button", {
      key: tab.id,
      role: "tab",
      "aria-selected": this.attrs.active === tab.id,
      className: 'Millwright-tab' + (this.attrs.active === tab.id ? ' is-active' : ''),
      onclick: () => this.attrs.choose(tab.id)
    }, tab.label, tab.badge > 0 ? m("span", {
      className: "Millwright-count"
    }, tab.badge) : null)));
  }
}
flarum.reg.add('ernestdefoe-millwright', 'admin/components/PageTabs', PageTabs);