import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
/** The Installed tab's line about the last update check, and the button that runs one. */
export default class CheckLine extends Component {
  /**
   * The count is always shown WITH its age and its blind spots. "1 newer
   * version" is a claim; "1 newer version, checked 2 hours ago, 9 packages could
   * not be checked" is the truth, and only the second lets somebody decide
   * whether to believe it.
   */
  view() {
    const n = this.attrs.count;
    const uncheckable = (this.attrs.updates.uncheckable || []).length;
    const tracking = (this.attrs.updates.tracking || []).length;
    const age = this.checkAge();

    // Never checked: there is no result to state, only the prompt (ClaudiusH, 2026-10-09:
    // "up to date" beside "check for updates" contradicted itself).
    const checkedAt = this.attrs.updates.checkedAt;
    if (!checkedAt) {
      return m("div", {
        className: "Millwright-checkline Millwright-checkline--overdue"
      }, m("p", {
        className: "Millwright-checkPrompt"
      }, app.translator.trans('ernestdefoe-millwright.admin.updater.check_overdue')), this.checkButton(age));
    }
    return m("div", {
      className: 'Millwright-checkline Millwright-checkline--' + age
    }, age === 'overdue' ? m("p", {
      className: "Millwright-checkPrompt"
    }, app.translator.trans('ernestdefoe-millwright.admin.updater.check_overdue')) : null, m("span", null, m("b", null, n === 0 && !this.attrs.coreNewer ? app.translator.trans('ernestdefoe-millwright.admin.updater.up_to_date') : n === 0 ? app.translator.trans('ernestdefoe-millwright.admin.updater.core_newer') : [app.translator.trans('ernestdefoe-millwright.admin.updater.some_newer', {
      count: n
    }), this.attrs.coreNewer ? ' ' + app.translator.trans('ernestdefoe-millwright.admin.updater.core_newer_too', {}, true) : '']), ' ', app.translator.trans('ernestdefoe-millwright.admin.updater.last_update_checked_at', {
      when: this.ago(checkedAt)
    }), uncheckable > 0 ? ' ' + app.translator.trans('ernestdefoe-millwright.admin.updater.uncheckable', {
      count: uncheckable
    }, true) : '', tracking > 0 ? ' ' + app.translator.trans('ernestdefoe-millwright.admin.updater.tracking', {
      count: tracking
    }, true) : ''), this.checkButton(age));
  }

  /**
   * How hard to ask, by how old the last check is (ClaudiusH, 2026-10-09):
   * within the week, an ordinary button; older than that, or never, a primary
   * button and a prompt that says why it matters. Always a button, never a
   * link: it is the main action on the Installed tab (ClaudiusH, 2026-10-27).
   */
  checkAge() {
    const at = this.attrs.updates.checkedAt;
    if (!at) return 'overdue';
    const days = (Date.now() / 1000 - at) / 86400;
    return days < 1 ? 'fresh' : days <= 7 ? 'recent' : 'overdue';
  }
  checkButton(age) {
    const className = age === 'overdue' ? 'Button Button--primary' : 'Button';
    return m(Button, {
      className: className + ' Millwright-checkNow',
      disabled: this.attrs.checking
      // A spinner as well as the words: "Checking…" alone reads as a label.
      ,
      icon: this.attrs.checking ? 'fas fa-circle-notch fa-spin' : undefined,
      onclick: () => this.attrs.check()
    }, this.attrs.checking ? app.translator.trans('ernestdefoe-millwright.admin.updater.checking') : age === 'fresh' ? app.translator.trans('ernestdefoe-millwright.admin.updater.check_now') : app.translator.trans('ernestdefoe-millwright.admin.updater.check_for_updates'));
  }
  ago(unix) {
    const mins = Math.max(1, Math.round(Date.now() / 1000 - unix) / 60);
    if (mins < 60) return app.translator.trans('ernestdefoe-millwright.admin.updater.ago.minutes', {
      count: Math.round(mins)
    }, true);
    const hours = Math.round(mins / 60);
    return hours < 48 ? app.translator.trans('ernestdefoe-millwright.admin.updater.ago.hours', {
      count: hours
    }, true) : app.translator.trans('ernestdefoe-millwright.admin.updater.ago.days', {
      count: Math.round(hours / 24)
    }, true);
  }
}
flarum.reg.add('ernestdefoe-millwright', 'admin/components/CheckLine', CheckLine);